     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      }
     ],
     "returns": "PaymentOrder",
     "legacy_output": null
    },
    {
     "name": "markPaid",
     "description": "Rewrites the order as paid with its movement number and commission (REWRITE FILE ORDENES).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      },
      {
