       "type": "text(fixed,1,iso8859-1)",
       "column": null,
       "legacy": "ORD_ESTADO"
      },
      {
       "name": "movementNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "ORD_MOVIM"
      },
      {
