   "name": "AccountRepository",
   "entity": "Account",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumberForUpdate",
     "description": "Reads the account by number and locks the row (READ FILE CUENTAS UPDATE). Empty when it does not exist (NOTFND).",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      }
     ],
     "returns": "Account",
     "legacy_output": null
    },
    {
     "name": "updateBalance",
     "description": "Rewrites the account with its new balance (REWRITE FILE CUENTAS).",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      },
      {
       "name": "balance",
       "type": "decimal(13,2,signed)",
       "column": null,
       "legacy": "CTA_SALDO"
      }
     ],
     "returns": "int",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "DebitGateway",
   "entity": null,
   "legacy_program": null,
   "methods": [
    {
     "name": "debit",
     "description": "Debits an account (replaces the LINK from PAGOORD to PAGODEB). Implemented in-process by the DebitAccount use case inside the caller's transaction. Returns the legacy DEB-RESP as a number: 0 debited, 10 inactive, 20 insufficient balance, 30 not found, 40 type mismatch.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "DEB_CUENTA"
      },
      {
       "name": "accountType",
       "type": "text(fixed,3,iso8859-1)",
       "column": null,
       "legacy": "DEB_TIPO"
      },
      {
