   "entity": null,
   "legacy_program": "PAGOMOV",
   "methods": [
    {
     "name": "registerMovement",
     "description": "Registers the payment movement for an order and returns the movement number (LINK to PAGOMOV, whose source is not available: stubbed).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "MOV_ORDEN"
      }
     ],
     "returns": "long",
     "legacy_output": "MOV_NUMERO"
    }
   ]
  }
 ],
 "use_cases": [
