     "column": null,
     "legacy": "ORDEN"
    },
    {
     "name": "companyId",
     "type": "text(fixed,5,iso8859-1)",
     "column": null,
     "legacy": "EMPRESA"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
