     "legacy": "CUENTA"
    },
    {
     "name": "amount",
     "type": "decimal(11,2,signed)",
     "column": null,
     "legacy": "VALOR"
    },
    {
     "name": "channel",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "CANAL"
    },
    {
     "name": "approvalKey",
     "type": "text(var,6,iso8859-1)",
     "column": null,
     "legacy": "CLAVE"
    }
   ],
   "outputs": [
    {
     "name": "orderNumber",
     "type": "text(fixed,7,iso8859-1)",
     "column": null,
     "legacy": "RORDEN"
    },
    {
