   "legacy_program": "PAGOORD",
   "legacy_message": "MENSAJE"
  },
  {
   "name": "DebitAccount",
   "description": "Debits an account: it must exist, have the requested type, be active and have enough balance (a debit equal to the balance is accepted). Then it reduces the balance.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005"
   ],
   "inputs": [
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "DEB_CUENTA"
    },
    {
