     "legacy_code": "40",
     "message": "EL TIPO DE CUENTA NO COINCIDE"
    },
    {
     "code": "ACCOUNT_INACTIVE",
     "legacy_code": "10",
     "message": "CUENTA INACTIVA"
    },
    {
     "code": "INSUFFICIENT_BALANCE",
     "legacy_code": "20",
     "message": "SALDO INSUFICIENTE"
    }
   ],
   "ports": [
    "AccountRepository"
   ],
   "http_method": "POST",
   "path": "/accounts/debits",
   "legacy_program": "PAGODEB",
   "legacy_message": "DEB_RESP"
  },
  {
   "name": "SelectMenuOption",
   "description": "Interprets the payments menu option: '1' opens payment of orders, '9' ends the session, any other option is rejected.",
   "rules": [
    "RULE-006"
   ],
   "inputs": [
    {
     "name": "option",
     "type": "text(fixed,1,iso8859-1)",
     "column": null,
