     "legacy_code": "OTHER",
     "message": "OPCION NO VALIDA"
    }
   ],
   "ports": [],
   "http_method": "POST",
   "path": "/payments/menu/options",
   "legacy_program": "PAGOMNU",
   "legacy_message": "MENSAJEO"
  }
 ],
 "decisions": [
  {
   "title": "One transaction per payment replaces SYNCPOINT",
   "context": "PAGOORD debits the account (PAGODEB), links PAGOMOV, rewrites the order and only then issues SYNCPOINT.",
   "decision": "PayOrder runs in a single database transaction. DebitAccount joins it when called through DebitGateway. Any business error or exception rolls back everything.",
   "consequences": "The debit, the movement registration and the order update are atomic. The legacy SYNCPOINT disappears."
  },
  {
   "title": "Pessimistic locking replaces READ ... UPDATE",
   "context": "The legacy reads ORDENES and CUENTAS with UPDATE, which holds the record until the task ends.",
   "decision": "findByKeyForUpdate and findByNumberForUpdate use SELECT ... FOR UPDATE, in the legacy order (order first, then account).",
   "consequences": "Concurrent payments of the same order or debits of the same account are serialized, as before."
  },
  {
   "title": "PAGODEB becomes a use case called in-process through DebitGateway",
   "context": "PAGOORD calls PAGODEB with LINK and a COMMAREA. PAGODEB answers with a response code (00, 10, 20, 30, 40).",
   "decision": "The debit logic lives only in the DebitAccount use case, also exposed as POST /accounts/debits. PayOrder reaches it through DebitGateway and receives the legacy code as a number. It maps 10 to ACCOUNT_INACTIVE, 20 to INSUFFICIENT_BALANCE and any other code (30, 40) to INVALID_ACCOUNT.",
   "consequences": "No duplicated rules. PAGODEB runs for real in the recorded traces, so the port has no legacy_program and is not stubbed in the replay. The effect of the debit is checked in the CUENTAS table."
  },
  {
   "title": "PAGOMOV is stubbed",
   "context": "The source of PAGOMOV is not available.",
   "decision": "MovementGateway is a port with a stub adapter. The replay uses the stubs recorded in the traces.",
   "consequences": "The real movement numbering must be implemented or integrated before going live."
  },
  {
   "title": "Amount is received in currency units",
   "context": "The legacy screen sends VALORI as 11 digits and PAGOORD converts it with NUMVAL / 100. The traces give the value as '1500.00'.",
   "decision": "The API receives amount as decimal(11,2). The comparison with the order amount is exact (scale 2, compareTo), with no rounding.",
   "consequences": "The client sends 1500.00 instead of the screen format. Any difference of one cent rejects the payment, as before."
  },
  {
   "title": "Identifiers are received as text and validated inside the use case",
   "context": "ORDENI, EMPRESAI and CUENTAI are alphanumeric on the screen and RULE-008 rejects a non-numeric or zero order number.",
   "decision": "orderNumber, companyId and accountNumber are text in PayOrder. A non-numeric or zero order number gives INVALID_ORDER_NUMBER. A non-numeric company gives ORDER_NOT_FOUND. A non-numeric account gives INVALID_ACCOUNT.",
   "consequences": "The last two are interpretations of the legacy behaviour for a non-numeric key. Screen checks (PF keys, TECLA NO VALIDA, BMS maps) are not migrated."
  },
  {
   "title": "Validation order and short circuit",
   "context": "RULE-007: validation, read, commission and debit, registration.",
   "decision": "PayOrder validates in the legacy order (order number, account type, channel, approval key), then reads the order (exists, pending, amount), calculates the commission, debits and registers. The first error ends the use case.",
   "consequences": "Only one error message is reported per request, as in the legacy."
  },
  {
   "title": "Commarea state is not persisted",
   "context": "The pseudo-conversational commarea carries state between screens. RULE-017 sets CA-ULTIMA-ORDEN.",
   "decision": "The service is stateless. The paid order number is returned as orderNumber. The menu navigation (XCTL) is the action returned by SelectMenuOption.",
   "consequences": "The client keeps any session context."
  },
  {
   "title": "Legacy status codes kept",
   "context": "Orders use 'P' (pending) and 'G' (paid). Accounts use 'A' (active) and 'I' (inactive).",
   "decision": "The values are kept in the new tables. Columns are renamed to English snake_case and FILLER is not migrated.",
   "consequences": "Data migrates without conversion."
  }
 ],
 "masks": [],
 "infrastructure": []
}

Use case: DebitAccount

Rules:
[
 {
  "id": "RULE-001",
  "name": "Debit rejected when account does not exist",
  "category": "validation",
  "priority": "P0",
  "statement": "If the READ of file CUENTAS by DEB-CUENTA returns WS-RESP = DFHRESP(NOTFND), the debit is refused by setting DEB-RESP to '30'.",
  "condition": "WS-RESP = DFHRESP(NOTFND) after reading CUENTAS by DEB-CUENTA",
  "action": "Set DEB-RESP to '30'; balance is not changed and no rewrite occurs",
  "inputs": [
   {
    "name": "DEB-CUENTA",
    "type": "decimal(10,0,unsigned)",
    "description": ""
   },
   {
    "name": "WS-RESP",
    "type": "integer(32,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Account not on file\n Given no CUENTAS record exists for account 1234567890\n When a debit of 100.00 is requested for account 1234567890\n Then the response code is '30'\n And no balance is changed"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 18,
    "line_end": 23
   }
  ]
 },
 {
  "id": "RULE-002",
  "name": "Debit rejected when account type differs from requested type",
  "category": "validation",
  "priority": "P0",
  "statement": "When the account type on the account (CTA-TIPO) differs from the account type in the debit request (DEB-TIPO), the debit response code DEB-RESP is set to '40'.",
  "condition": "Account found AND CTA-TIPO NOT = DEB-TIPO",
  "action": "Set DEB-RESP to '40'; balance is not changed",
  "inputs": [
   {
    "name": "CTA-TIPO",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   },
   {
    "name": "DEB-TIPO",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Type mismatch\n Given account 1234567890 exists with type 'AHO'\n When a debit is requested for that account with type 'COR'\n Then the response code is '40'\n And the balance is unchanged"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 24,
    "line_end": 25
   }
  ]
 },
 {
  "id": "RULE-003",
  "name": "Debit rejected when account is not active",
  "category": "validation",
  "priority": "P0",
  "statement": "If the account is not active (NOT CTA-ACTIVA), the debit is refused by setting DEB-RESP to '10'.",
  "condition": "Account found AND type matches AND NOT CTA-ACTIVA",
  "action": "Set DEB-RESP to '10'; balance is not changed",
  "inputs": [
   {
    "name": "CTA-ESTADO",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Inactive account\n Given account 1234567890 exists, the type matches and the account is not active\n When a debit of 50.00 is requested\n Then the response code is '10'\n And the balance is unchanged"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 26,
    "line_end": 27
   }
  ]
 },
 {
  "id": "RULE-004",
  "name": "Debit rejected for insufficient balance",
  "category": "validation",
  "priority": "P0",
  "statement": "If the account balance (CTA-SALDO) is strictly less than the requested debit amount (DEB-MONTO), the debit is refused by setting DEB-RESP to '20'. A debit equal to the balance does not trigger this rejection.",
  "condition": "Account found, type matches, account active AND CTA-SALDO < DEB-MONTO",
  "action": "Set DEB-RESP to '20'; balance is not changed",
  "inputs": [
   {
    "name": "CTA-SALDO",
    "type": "decimal(13,2,signed)",
    "description": ""
   },
   {
    "name": "DEB-MONTO",
    "type": "decimal(13,2,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Insufficient funds\n Given an active account with balance 80.00 and matching type\n When a debit of 100.00 is requested\n Then the response code is '20'\n And the balance stays 80.00",
   "Scenario: Exact balance\n Given an active account with balance 100.00 and matching type\n When a debit of 100.00 is requested\n Then the debit is accepted and the balance becomes 0.00"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 28,
    "line_end": 29
   }
  ]
 },
 {
  "id": "RULE-005",
  "name": "Successful debit reduces account balance",
  "category": "calculation",
  "priority": "P0",
  "statement": "When none of the preceding WHEN rejection branches of the evaluation matches (WHEN OTHER), the program performs 1000-DEBITAR: it subtracts DEB-MONTO from CTA-SALDO, rewrites the CUENTAS record from CTA-REGISTRO, and sets DEB-RESP to '00'.",
  "condition": "None of the rejection conditions (30, 40, 10, 20) applies",
  "action": "CTA-SALDO = CTA-SALDO - DEB-MONTO; rewrite the CUENTAS record; set DEB-RESP to '00'",
  "inputs": [
   {
    "name": "CTA-SALDO",
    "type": "decimal(13,2,signed)",
    "description": ""
   },
   {
    "name": "DEB-MONTO",
    "type": "decimal(13,2,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "CTA-SALDO",
