package com.bank.payments.application;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.bank.payments.adapters.in.rest.DebitAccountRequest;
import com.bank.payments.adapters.in.rest.DebitAccountResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.port.AccountRepository;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;

class DebitAccountServiceTest {

    private static final Long ACCOUNT_NUMBER = 1234567890L;

    /** In-memory fake of the account port that records the locks and rewrites. */
    private static final class FakeAccountRepository implements AccountRepository {
        private final Account account;
        final List<Long> lockedReads = new ArrayList<>();
        final List<Object[]> updates = new ArrayList<>();

        FakeAccountRepository(Account account) {
            this.account = account;
        }

        @Override
        public Optional<Account> findByNumberForUpdate(Long accountNumber) {
            lockedReads.add(accountNumber);
            if (account != null && account.accountNumber().equals(accountNumber)) {
                return Optional.of(account);
            }
            return Optional.empty();
        }

        @Override
        public int updateBalance(Long accountNumber, BigDecimal balance) {
            updates.add(new Object[] {accountNumber, balance});
            return 1;
        }
    }

    private static Account account(String type, String balance, String status) {
        return new Account(ACCOUNT_NUMBER, type, new BigDecimal(balance), status);
    }

    private static DebitAccountRequest request(String type, String amount) {
        return new DebitAccountRequest(ACCOUNT_NUMBER, type, new BigDecimal(amount));
    }

    private static void assertRejected(DebitAccountService service, DebitAccountRequest request,
                                       String code, String legacyCode) {
        assertThatThrownBy(() -> service.execute(request))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> {
                    BusinessError error = (BusinessError) e;
                    assertThat(error.code()).isEqualTo(code);
                    assertThat(error.legacyCode()).isEqualTo(legacyCode);
                });
    }

    @Test
    void account_not_on_file() {
        FakeAccountRepository repo = new FakeAccountRepository(null);
        DebitAccountService service = new DebitAccountService(repo);

        assertRejected(service, request("AHO", "100.00"), "ACCOUNT_NOT_FOUND", "30");
        assertThat(repo.updates).isEmpty();
    }

    @Test
    void type_mismatch() {
        FakeAccountRepository repo = new FakeAccountRepository(account("AHO", "500.00", "A"));
        DebitAccountService service = new DebitAccountService(repo);

        assertRejected(service, request("COR", "100.00"), "ACCOUNT_TYPE_MISMATCH", "40");
        assertThat(repo.updates).isEmpty();
    }

    @Test
    void inactive_account() {
        FakeAccountRepository repo = new FakeAccountRepository(account("AHO", "500.00", "I"));
        DebitAccountService service = new DebitAccountService(repo);

        assertRejected(service, request("AHO", "50.00"), "ACCOUNT_INACTIVE", "10");
        assertThat(repo.updates).isEmpty();
    }

    @Test
    void type_mismatch_is_checked_before_inactive() {
        FakeAccountRepository repo = new FakeAccountRepository(account("AHO", "500.00", "I"));
        DebitAccountService service = new DebitAccountService(repo);

        assertRejected(service, request("COR", "50.00"), "ACCOUNT_TYPE_MISMATCH", "40");
        assertThat(repo.updates).isEmpty();
    }

    @Test
    void inactive_is_checked_before_insufficient_balance() {
        FakeAccountRepository repo = new FakeAccountRepository(account("AHO", "10.00", "I"));
        DebitAccountService service = new DebitAccountService(repo);

        assertRejected(service, request("AHO", "50.00"), "ACCOUNT_INACTIVE", "10");
        assertThat(repo.updates).isEmpty();
    }

    @Test
    void insufficient_funds() {
        FakeAccountRepository repo = new FakeAccountRepository(account("AHO", "80.00", "A"));
        DebitAccountService service = new DebitAccountService(repo);

        assertRejected(service, request("AHO", "100.00"), "INSUFFICIENT_BALANCE", "20");
        assertThat(repo.updates).isEmpty();
    }

    @Test
    void exact_balance() {
        FakeAccountRepository repo = new FakeAccountRepository(account("AHO", "100.00", "A"));
        DebitAccountService service = new DebitAccountService(repo);

        DebitAccountResponse response = service.execute(request("AHO", "100.00"));

        assertThat(response.newBalance()).isEqualByComparingTo(new BigDecimal("0.00"));
        assertThat(response.responseCode()).isEqualTo("00");
        assertThat(repo.updates).hasSize(1);
        assertThat(repo.updates.get(0)[0]).isEqualTo(ACCOUNT_NUMBER);
        assertThat((BigDecimal) repo.updates.get(0)[1]).isEqualByComparingTo(new BigDecimal("0.00"));
    }

    @Test
    void successful_debit() {
        FakeAccountRepository repo = new FakeAccountRepository(account("AHO", "500.00", "A"));
        DebitAccountService service = new DebitAccountService(repo);

        DebitAccountResponse response = service.execute(request("AHO", "120.50"));

        assertThat(response.newBalance()).isEqualByComparingTo(new BigDecimal("379.50"));
        assertThat(response.responseCode()).isEqualTo("00");
        assertThat(repo.lockedReads).containsExactly(ACCOUNT_NUMBER);
        assertThat(repo.updates).hasSize(1);
        assertThat(repo.updates.get(0)[0]).isEqualTo(ACCOUNT_NUMBER);
        assertThat((BigDecimal) repo.updates.get(0)[1]).isEqualByComparingTo(new BigDecimal("379.50"));
    }
}
